        this.image = image;
        this.title = title;
        this.description = description;
        this.field1 = field1;
        this.field2 = field2;
        this.field3 = field3;
        this.field4 = field4;
        this.isChapter = isChapter;
        this.link = link;
        this.openInWebView = openInWebView;
    }

    function safeText ( value ) {
        return value == null ? '' : String( value );
    }

    function pickTitle ( titles ) {
        try {
            if ( titles && titles.en ) return safeText( titles.en );
            var keys = Object.keys( titles || {} );
            return keys.length ? safeText( titles[ keys[ 0 ] ] ) : 'Untitled';
        } catch ( e ) {
            return 'Untitled';
        }
    }

    function pickDescription ( descriptions ) {
        try {
            if ( descriptions && descriptions.en ) return safeText( descriptions.en ).replace( /[\r\n]+/g, ' ' );
            var keys = Object.keys( descriptions || {} );
            return keys.length ? safeText( descriptions[ keys[ 0 ] ] ).replace( /[\r\n]+/g, ' ' ) : '';
        } catch ( e ) {
            return '';
        }
    }

    function getCoverFile ( relationships ) {
        try {
            for ( var i = 0; i < ( relationships || [] ).length; i++ ) {
                var relation = relationships[ i ];
                if ( relation && relation.type === 'cover_art' && relation.attributes && relation.attributes.fileName ) {
                    return relation.attributes.fileName;
                }
            }
        } catch ( e ) {}
        return '';
    }

    function tryParseResponse ( text ) {
        try {
            var raw = safeText( text ).replace( /^\uFEFF/, '' ).trim();
            if ( raw.indexOf( '/*' ) === 0 ) {
                raw = raw.replace( /^\/\*/, '' ).replace( /\*\/$/, '' ).trim();
            }
            if ( raw.charAt( 0 ) === '{' && raw.charAt( raw.length - 1 ) === '}' ) {
                return JSON.parse( raw );
            }
        } catch ( e ) {}
        return null;
    }

    function readJsonResponse ( ) {
        var nodes = [];
        try { nodes = document.querySelectorAll( 'pre, script, body' ); } catch ( e ) {}
        for ( var i = 0; i < nodes.length; i++ ) {
            var node = nodes[ i ];
            var candidates = [
                node && node.textContent,
                node && node.innerText,
                node && node.innerHTML
            ];
            for ( var j = 0; j < candidates.length; j++ ) {
                var parsed = tryParseResponse( candidates[ j ] );
                if ( parsed && parsed.data ) return parsed;
            }
        }

        try {
            var bodyText = document.body ? ( document.body.textContent || document.body.innerText || '' ) : '';
            var start = bodyText.indexOf( '{"result"' );
            if ( start < 0 ) start = bodyText.indexOf( '{"data"' );
            if ( start >= 0 ) {
                var parsedBody = tryParseResponse( bodyText.substring( start ) );
                if ( parsedBody && parsedBody.data ) return parsedBody;
            }
        } catch ( e ) {}
        return null;
    }

    function complete ( ) {
        try {
            if (
                typeof KETSU_ASYNC !== 'undefined' &&
                window.webkit &&
                window.webkit.messageHandlers &&
                window.webkit.messageHandlers.EXECUTE_KETSU_ASYNC
            ) {
                window.webkit.messageHandlers.EXECUTE_KETSU_ASYNC.postMessage( '' );
            }
        } catch ( e ) {}
    }

    var savedData = document.getElementById( 'ketsu-final-data' );
    var apiHeaders = [
        new KeyValue( 'Accept', 'application/json' ),
        new KeyValue( 'User-Agent', 'KETSU MangaDex Module/4.75 (personal-use)' )
    ];
    var imageHeaders = [
        new KeyValue( 'Referer', 'https://mangadex.org/' ),
        new KeyValue( 'User-Agent', 'KETSU MangaDex Module/4.75 (personal-use)' )
    ];

    var json = readJsonResponse();
    var searchArray = [];

    if ( json && Array.isArray( json.data ) ) {
        for ( var mIndex = 0; mIndex < json.data.length; mIndex++ ) {
            var manga = json.data[ mIndex ] || {};
            var attributes = manga.attributes || {};
            var title = pickTitle( attributes.title );
            var description = pickDescription( attributes.description );
            var coverFile = getCoverFile( manga.relationships );
            var coverURL = coverFile
                ? 'https://uploads.mangadex.org/covers/' + manga.id + '/' + coverFile
                : 'https://i.postimg.cc/4d38NsqH/Manga-Dex-logo.png';

            var imageRequest = new ModuleRequest( coverURL, 'get', imageHeaders, null );
            var detailRequest = new ModuleRequest(
                'https://api.mangadex.org/manga/' + manga.id + '?includes[]=cover_art',
                'get',
                apiHeaders,
                null
            );

            searchArray.push(
                new Data( imageRequest, title, description, '', '', '', '', false, detailRequest, false )
            );
        }
    }

    var output = [
        new Output(
            CellDesings.wide11,
            Orientation.vertical,
            DefaultLayouts.none,
            Paging.none,
            new Section( '', false ),
            null,
            searchArray
        )
    ];

    var searchObject = new Search(
        new ModuleRequest( '', 'get', apiHeaders, null ),
        new Extra( [ new Commands( '', apiHeaders ) ], apiHeaders ),
        '',
        new JavascriptConfig( true, false, '' ),
        output
    );

    savedData.innerHTML = JSON.stringify( searchObject );
    complete();
} catch ( e ) {
    try { console.error( e && e.message ? e.message : e ); } catch ( ignored ) {}
    try {
        var fallbackData = document.getElementById( 'ketsu-final-data' );
        if ( fallbackData ) {
            fallbackData.innerHTML = JSON.stringify( {
                request: { url: '', method: 'get', headers: [], httpBody: null },
                extra: { commands: [], extraInfo: [] },
                separator: '',
                javascriptConfig: { removeJavascript: true, loadInWebView: false, javaScript: '' },
                output: []
            } );
        }
    } catch ( ignored ) {}
    try {
        if (
            typeof KETSU_ASYNC !== 'undefined' &&
            window.webkit &&
            window.webkit.messageHandlers &&
            window.webkit.messageHandlers.EXECUTE_KETSU_ASYNC
        ) {
            window.webkit.messageHandlers.EXECUTE_KETSU_ASYNC.postMessage( '' );
        }
    } catch ( ignored ) {}
}
